            # condition A: non-bg cells form exactly one 4-connected blob of uniform color C, plus <=1 foreign pixel attached to it, no other colors
            nb=[p for p,v in enumerate(flat) if v!=bg]
            if len(nb)<2: continue
            nbset=set(nb); st=[nb[0]]; comp={nb[0]}
            while st:
                a,b=st.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(a+dy,b+dx)
                    if p in nbset and p not in comp: comp.add(p); st.append(p)
            rest=nbset-comp
            if len(rest)!=1: continue
            fr=rest.pop(); fa,fb=(fr)//w2, fr%w2
            cc=g[y+fa][x+fb]
            if any(abs(fa-a)+abs(fb-b)<=1 for a,b in comp) and len({v for v,_ in [(flat[i],i) for i in comp]})==1:
                pass
            else: continue
            res.append(((y,x),cc,flat[fa*w2+fb]))
