# Criterion refinement: the winning window in each demo = bbox of the stray's neighboring dominant-color component,
# i.e., window = [stray]+surrounding solid T block. Verify: compute per demo, list strays with their T-components' bboxes == output window.
def solve(g,o=None):
    from collections import Counter, deque
    bgv=Counter(v for r_ in g for v in r_).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    # flood components of non-bg
    seen=[[False]*W for _ in range(H)]; res=[]
    for a in range(H):
        for b in range(W):
            if g[a][b]!=bgv and not seen[a][b]:
                dq=deque([(a,b)]); seen[a][b]=True; col=g[a][b]; cells=[(a,b)]; cnt=1
                while dq:
                    p=dq.popleft()
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            q=(p[0]+dy,p[1]+dx)
